import React, { useEffect, useRef, useState } from "react";
import { watchlist } from "../data/data";

const BACKEND_URL = "https://zerodha-backend-o227.onrender.com";
const WS_URL = BACKEND_URL.replace("https://", "wss://");

const WatchList = () => {
  const [stocks, setStocks] = useState(watchlist);
  const [connectionStatus, setConnectionStatus] = useState("connecting");
  const socketRef = useRef(null);

  useEffect(() => {
    let socket;
    let reconnectTimer;

    const connectSocket = () => {
      socket = new WebSocket(WS_URL);
      socketRef.current = socket;

      socket.onopen = () => {
        setConnectionStatus("connected");

        const symbols = watchlist
          .map((stock) => stock.name)
          .filter(Boolean);

        socket.send(
          JSON.stringify({
            type: "subscribe",
            symbols,
          })
        );
      };

      socket.onmessage = (event) => {
        try {
          const message = JSON.parse(event.data);

          if (message.type !== "prices" || !Array.isArray(message.data)) {
            return;
          }

          const priceMap = {};

          message.data.forEach((item) => {
            if (item && item.symbol) {
              priceMap[item.symbol.toUpperCase()] = item;
            }
          });

          setStocks((currentStocks) =>
            currentStocks.map((stock) => {
              const symbol = String(stock.name || "").toUpperCase();
              const livePrice = priceMap[symbol];

              if (!livePrice) {
                return stock;
              }

              return {
                ...stock,
                price: livePrice.price,
                ltp: livePrice.ltp,
                day: livePrice.day,
                isLoss: livePrice.isLoss,
                change: livePrice.change,
                changePercent: livePrice.changePercent,
              };
            })
          );
        } catch (error) {
          console.error("Invalid WebSocket message:", error);
        }
      };

      socket.onerror = (error) => {
        console.error("WebSocket error:", error);
        setConnectionStatus("disconnected");
      };

      socket.onclose = () => {
        setConnectionStatus("disconnected");

        reconnectTimer = setTimeout(() => {
          setConnectionStatus("connecting");
          connectSocket();
        }, 3000);
      };
    };

    connectSocket();

    return () => {
      clearTimeout(reconnectTimer);

      if (socket) {
        socket.close();
      }

      socketRef.current = null;
    };
  }, []);

  return (
    <div className="watchlist-container">
      <div className="title">
        <h3>Watchlist</h3>

        <span
          style={{
            fontSize: "12px",
            color:
              connectionStatus === "connected"
                ? "green"
                : connectionStatus === "connecting"
                ? "orange"
                : "red",
          }}
        >
          ●{" "}
          {connectionStatus === "connected"
            ? "Live"
            : connectionStatus === "connecting"
            ? "Connecting..."
            : "Disconnected"}
        </span>
      </div>

      <div className="list">
        {stocks.map((stock, index) => {
          const isLoss =
            stock.isLoss ||
            Number(stock.changePercent || 0) < 0 ||
            Number(stock.change || 0) < 0;

          return (
            <div className="watchlist-item" key={stock.name || index}>
              <div className="item">
                <p className="stock-name">{stock.name}</p>

                <div className="price-info">
                  <span className="price">
                    ₹
                    {Number(stock.price || 0).toLocaleString("en-IN", {
                      minimumFractionDigits: 2,
                      maximumFractionDigits: 2,
                    })}
                  </span>

                  <span
                    className={isLoss ? "loss" : "profit"}
                    style={{ marginLeft: "8px" }}
                  >
                    {stock.changePercent !== undefined
                      ? `${Number(stock.changePercent).toFixed(2)}%`
                      : stock.day}
                  </span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default WatchList;
